INSERT INTO `prova` VALUES (1,'PAES2026_OBJ','UNICA','OBJETIVA_REDAÇÃO',2026,'DOMINGO','2025-11-30'),(2,'PAES2026_OBJ_PROD.TEXTUAL','UNICA','OBJETIVA_PROD.TEXTUAL',2026,'DOMINGO','2025-11-30');
